with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'أنماط الطقس والمناخ في شرق المتوسط وبلاد الشام','الجغرافيا المناخية والمنخفضات المتوسطية ومنخفض البحر الأحمر والاندفاعات الباردة والثلوج والعواصف والغبار والأمطار التضاريسية وتغير المناخ الإقليمي.',26,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'مناخ شرق المتوسط وبلاد الشام',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأنظمة الجوية الإقليمية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الظواهر الشتوية الإقليمية',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الظواهر الجوية الإقليمية',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('eastern-mediterranean-climate-geography','الجغرافيا المناخية لشرق المتوسط وبلاد الشام','تأثير البحر والتضاريس والعروض الجغرافية في أنماط الطقس الإقليمية.','{"blocks":[{"type":"text","text":"يتأثر مناخ شرق المتوسط بموقعه بين العروض الوسطى وشبه المدارية وبقربه من البحر والصحارى والمرتفعات."},{"type":"text","text":"تتميز مناطق ساحلية كثيرة بموسمية مطرية شتوية وجفاف صيفي نسبي، مع تباين واضح بين المواقع."},{"type":"text","text":"تؤثر سلاسل الجبال الساحلية والداخلية في الرفع التضاريسي وتوزيع الهطول والظل المطري."},{"type":"text","text":"تختلف درجات الحرارة بين الساحل والداخل والمرتفعات والبادية بسبب الارتفاع والبعد عن البحر والغطاء الأرضي."},{"type":"text","text":"تؤثر الرياح الغربية والجنوبية الغربية الرطبة في نقل الرطوبة من المتوسط نحو اليابسة خلال حالات عديدة."},{"type":"text","text":"قد تتعرض المنطقة لكتل هوائية باردة من الشمال أو الشمال الغربي، وأخرى دافئة وجافة من الجنوب والشرق."},{"type":"text","text":"تختلف بداية موسم المطر ونهايته وكمياته بين سنة وأخرى بفعل الأنظمة الدورانية واسعة النطاق."},{"type":"text","text":"تتأثر المناطق الشرقية والداخلية بامتداد الصحارى ومصادر الغبار والتباين الحراري اليومي."},{"type":"text","text":"يجب استخدام سجلات محطات متعددة الارتفاعات والمواقع لفهم المناخ الإقليمي بدلاً من تعميم محطة واحدة."},{"type":"text","text":"تساعد خرائط التضاريس والبحر والغطاء الأرضي في تفسير الاختلافات المكانية."},{"type":"text","text":"مثال: قد تسجل منطقة جبلية ساحلية هطولاً أعلى من منطقة داخلية قريبة أثناء تدفق رطب عمودي على السفح."},{"type":"callout","text":"خلاصة: مناخ شرق المتوسط نتاج تفاعل البحر والتضاريس والدوران العام والكتل الهوائية."}]}',1860,55,'["تحديد العوامل الجغرافية المؤثرة","فهم التباين الساحلي والداخلي","شرح أثر التضاريس"]','مناخ شرق المتوسط وبلاد الشام'),
('eastern-mediterranean-cyclones','المنخفضات المتوسطية وتأثيرها في شرق المتوسط','نشأة المنخفضات ومساراتها والجبهات والهطول والرياح المصاحبة.','{"blocks":[{"type":"text","text":"تتكون المنخفضات المتوسطية ضمن بيئة العروض الوسطى وتتأثر بالتباين الحراري والاضطرابات العلوية."},{"type":"text","text":"قد تتطور المنخفضات فوق غرب أو وسط المتوسط ثم تتحرك شرقاً وفق مسار التيار الغربي وتوزيع الضغط."},{"type":"text","text":"ترتبط بعض الحالات بتفاعل أخدود علوي مع تدرج حراري ورطوبة سطح البحر."},{"type":"text","text":"تؤدي الجبهات الباردة والدافئة إلى تغيرات في الحرارة والرياح والسحب والهطول أثناء مرور المنخفض."},{"type":"text","text":"تختلف كمية الهطول بحسب مسار مركز المنخفض وموقع الجبهة واتجاه تدفق الرطوبة والتضاريس."},{"type":"text","text":"قد تشتد الرياح على السواحل والمرتفعات عند ازدياد تدرج الضغط أو مرور جبهة نشطة."},{"type":"text","text":"تستخدم خرائط الضغط السطحي و850 و700 و500 hPa لتشخيص البنية الرأسية وتطور المنخفض."},{"type":"text","text":"تساعد صور الأقمار والرادار والمحطات في متابعة نطاقات الهطول والتحقق من التوقعات."},{"type":"text","text":"قد يتغير مسار المنخفض أو توقيت وصول الجبهة بين أعضاء النماذج، لذلك تراجع السيناريوهات التجميعية."},{"type":"text","text":"لا يكفي وجود مركز منخفض قرب قبرص أو شرق المتوسط لتحديد كميات المطر؛ يلزم تحليل الرطوبة والرفع والحرارة والتضاريس."},{"type":"text","text":"مثال: مرور جبهة باردة من الغرب قد يسبب هطولاً على الساحل والجبال، بينما يتغير الامتداد الداخلي بحسب اتجاه الرياح وعمق الرطوبة."},{"type":"callout","text":"خلاصة: تحليل المنخفضات المتوسطية يتطلب ربط مسار النظام بالبنية العليا والرصد والتضاريس."}]}',1870,55,'["تمييز المنخفضات المتوسطية","تحليل مسارات الأنظمة","ربط المنخفض بالطبقات العليا"]','الأنظمة الجوية الإقليمية'),
('red-sea-trough-and-regional-interactions','منخفض البحر الأحمر وتفاعلاته الجوية','امتداد المنخفض الحراري شمالاً وتفاعله مع الأخاديد والكتل الهوائية.','{"blocks":[{"type":"text","text":"منخفض البحر الأحمر امتداد منخفض ضغط أو أخدود حراري يرتبط بمنطقة البحر الأحمر وشبه الجزيرة العربية وشمال شرق أفريقيا."},{"type":"text","text":"تختلف خصائصه وموقع محوره وعمقه بحسب الموسم والتوزيع الحراري والدوران الإقليمي."},{"type":"text","text":"قد يمتد الأخدود شمالاً نحو بلاد الشام أو شرق المتوسط، لكن امتداده لا يعني بالضرورة هطولاً واسعاً."},{"type":"text","text":"تزداد فرص الاضطرابات عندما يتفاعل الأخدود مع أخدود علوي أو هواء بارد في الطبقات الوسطى والعليا."},{"type":"text","text":"قد يؤدي التباين الحراري بين الطبقات إلى زيادة عدم الاستقرار إذا توافرت الرطوبة والرفع."},{"type":"text","text":"تؤثر مصادر الرطوبة من البحر الأحمر والبحر العربي والبحر المتوسط بحسب اتجاه التدفق وعمقه."},{"type":"text","text":"قد تنتج حالات حملية محلية عندما تتوافر الرطوبة والتقارب والتسخين أو الرفع التضاريسي."},{"type":"text","text":"تستخدم خرائط الضغط والرياح والرطوبة عند 850 و700 hPa والدوامية العلوية لتقييم الحالة."},{"type":"text","text":"قد تكون بعض الحالات مصحوبة بالغبار أو الرياح النشطة قبل وصول الهطول أو بالتزامن معه."},{"type":"text","text":"يجب التمييز بين الأخدود السطحي والمنخفض المغلق وبين تأثيره المحتمل في الطبقات العليا."},{"type":"text","text":"مثال: وجود أخدود البحر الأحمر مع منخفض علوي بارد قد يهيئ بيئة اضطرابية، لكن موقع الرفع والرطوبة يحدد مناطق الهطول."},{"type":"callout","text":"خلاصة: أثر منخفض البحر الأحمر يعتمد على تفاعله مع الأنظمة الأخرى وليس على وجوده وحده."}]}',1880,55,'["شرح خصائص منخفض البحر الأحمر","فهم التفاعل مع الأخاديد","تقييم فرص الحمل والهطول"]','الأنظمة الجوية الإقليمية'),
('sudan-low-and-thermal-trough','المنخفض السوداني والأخاديد الحرارية الإقليمية','الدوران الحراري شبه المداري وامتداد المنخفضات نحو شمال أفريقيا وشرق المتوسط.','{"blocks":[{"type":"text","text":"يشير المنخفض السوداني في الاستخدام السينوبتيكي الإقليمي إلى امتداد منخفض حراري أو أخدود يرتبط بتسخين مناطق شمال شرق أفريقيا."},{"type":"text","text":"تتغير قوة الامتداد وموقع محوره موسمياً مع انتقال نطاق التسخين والدوران شبه المداري."},{"type":"text","text":"قد يتجه امتداد الأخدود شمالاً أو شمال شرق نحو مصر وشرق المتوسط وفق الحالة العامة."},{"type":"text","text":"لا يعني وجود المنخفض الحراري وحده هطولاً؛ إذ قد يرتبط بهواء حار وجاف في بعض الحالات."},{"type":"text","text":"يمكن أن يتفاعل الأخدود مع اضطراب علوي أو تدفق رطب ليولد حالة عدم استقرار أو أمطاراً رعدية."},{"type":"text","text":"تؤثر الرياح الجنوبية والجنوبية الشرقية في نقل الهواء الدافئ والغبار من المناطق الداخلية والصحراوية."},{"type":"text","text":"تساعد خرائط الضغط السطحي والحرارة والرطوبة والارتفاعات العليا على تمييز المكون الحراري من الديناميكي."},{"type":"text","text":"قد تتباين آثار المنخفض بين شمال أفريقيا وشرق المتوسط بحسب موقع المحور وتوزيع الرطوبة."},{"type":"text","text":"تستخدم صور الأقمار والرادار والسبر لتحديد ما إذا كانت الحالة جافة أو رطبة أو غير مستقرة."},{"type":"text","text":"يجب عدم استخدام اسم النظام بديلاً عن وصف البنية الفعلية للضغط والحرارة والرطوبة."},{"type":"text","text":"مثال: امتداد حراري دافئ مع غياب الرفع والرطوبة قد يرفع الحرارة دون أن ينتج هطولاً."},{"type":"callout","text":"خلاصة: تحليل المنخفض السوداني يتطلب تحديد بنيته وموقعه وتفاعله مع الأنظمة العليا والرطوبة."}]}',1890,55,'["شرح المنخفض الحراري","فهم الامتداد الموسمي","تمييز التأثير الحراري والديناميكي"]','الأنظمة الجوية الإقليمية'),
('eastern-mediterranean-cold-air-outbreaks','الاندفاعات الباردة والكتل الهوائية نحو شرق المتوسط','مصادر الهواء البارد ومساراته والتبريد السطحي وتطور الحالات الشتوية.','{"blocks":[{"type":"text","text":"تحدث الاندفاعات الباردة عندما تنتقل كتلة هوائية أبرد من مناطق أعلى عرضاً أو من داخل القارات نحو شرق المتوسط."},{"type":"text","text":"تختلف خصائص الكتلة بحسب منطقة المصدر ومسارها فوق اليابسة أو البحر ومدة انتقالها."},{"type":"text","text":"قد يؤدي مرور الهواء البارد فوق مياه أدفأ نسبياً إلى زيادة عدم الاستقرار وتطور السحب الحملية."},{"type":"text","text":"تؤثر التضاريس في توجيه الهواء البارد وتراكمه في الأحواض والوديان، وقد تنتج فروق محلية كبيرة."},{"type":"text","text":"تستخدم خرائط 850 hPa ودرجة الحرارة والرطوبة والضغط السطحي لتتبع تقدم الكتلة الباردة."},{"type":"text","text":"تساعد سماكة الطبقة والارتفاعات الجيوپوتنسيالية على تشخيص عمق الهواء البارد."},{"type":"text","text":"قد تتزامن الاندفاعات الباردة مع جبهات وهطول ورياح نشطة، بحسب بنية المنخفض ومساره."},{"type":"text","text":"يحتاج توقع الصقيع إلى حرارة السطح والرياح والغطاء السحابي والتضاريس، لا حرارة الهواء عند مستوى واحد فقط."},{"type":"text","text":"قد تؤدي التغيرات في حرارة سطح البحر إلى تعديل السحب والهطول على المسارات البحرية."},{"type":"text","text":"مثال: تدفق هواء بارد فوق المتوسط قد يسبب زخات حملية قرب السواحل المواجهة للرياح إذا توافرت الرطوبة وعدم الاستقرار."},{"type":"callout","text":"خلاصة: الاندفاع البارد عملية ثلاثية الأبعاد تتأثر بالمصدر والمسار والبحر والتضاريس."}]}',1900,55,'["تحديد مصادر الكتل الباردة","تحليل مسارات الاندفاع","فهم أثر البحر والتضاريس"]','الأنظمة الجوية الإقليمية'),
('levant-snowfall-and-freezing-level','توقع الثلوج ومستوى التجمد في المرتفعات','الملف الحراري الرأسي ومستوى الصفر ودرجة البصيلة الرطبة وتراكم الثلوج.','{"blocks":[{"type":"text","text":"يتطلب توقع الثلوج في المرتفعات تحليل درجة الحرارة من السحب إلى السطح وليس الاعتماد على حرارة محطة واحدة."},{"type":"text","text":"يمثل مستوى التجمد الارتفاع الذي تصل عنده درجة الحرارة إلى الصفر تقريباً في ملف رأسي محدد."},{"type":"text","text":"قد يختلف مستوى التجمد عن مستوى تساقط الثلج بسبب التبريد التبخري ودرجة البصيلة الرطبة وعمليات الذوبان."},{"type":"text","text":"تساعد درجة البصيلة الرطبة في تقدير ظروف بقاء الهطول متجمداً قرب السطح، خاصة عند بدء الهطول في هواء جاف."},{"type":"text","text":"تؤثر شدة الهطول في التبريد التبخري وتغير مستوى الثلج خلال الحدث."},{"type":"text","text":"قد تتساقط الثلوج على ارتفاعات أقل أثناء هطول غزير أو مع اندفاع هواء بارد، بينما ترتفع الحدود مع الهواء الدافئ."},{"type":"text","text":"تؤثر التضاريس والاتجاه والظل والرياح في التراكم وإعادة توزيع الثلوج."},{"type":"text","text":"يجب التمييز بين ارتفاع خط الثلج وحدود الهطول الثلجي الفعلية وعمق التراكم."},{"type":"text","text":"تستخدم ملفات السبر وخرائط 850 و700 hPa وبيانات النماذج عالية الدقة لتقييم الملف الحراري."},{"type":"text","text":"تحتاج توقعات التراكم إلى مراعاة كثافة الثلج والذوبان والرياح وحرارة السطح."},{"type":"text","text":"مثال: قد يكون مستوى الصفر فوق قمة جبل بقليل، لكن التبريد أثناء الهطول يسمح بثلج رطب على القمة."},{"type":"callout","text":"خلاصة: توقع الثلوج يتطلب ملفاً حرارياً ورطوبياً رأسياً وتحليلاً محلياً للارتفاع والتراكم."}]}',1910,55,'["تحديد مستويات التجمد","فهم درجة البصيلة الرطبة","تقدير اختلاف الثلج مع الارتفاع"]','الظواهر الشتوية الإقليمية'),
('levant-convective-storms-and-flash-floods','العواصف الحملية والسيول في بلاد الشام','البيئات الحملية والتضاريس والتقارب والهطول الموضعي الغزير.','{"blocks":[{"type":"text","text":"تتكون العواصف الحملية عندما تتوفر رطوبة وعدم استقرار وآلية رفع تسمح بنمو السحب رأسياً."},{"type":"text","text":"قد تسهم السواحل والجبال والوديان في تنظيم التقارب والرفع وتحديد مواقع بدء الحمل."},{"type":"text","text":"تؤدي فروق التسخين بين اليابسة والبحر إلى نسائم محلية قد تتفاعل مع الرياح العامة."},{"type":"text","text":"قد ينتج عن التقاء تدفقات مختلفة مناطق تقارب ترفع الهواء وتدعم نمو السحب."},{"type":"text","text":"تتفاوت شدة العواصف مكانياً وقد تتركز الأمطار الغزيرة ضمن نطاقات ضيقة."},{"type":"text","text":"قد يؤدي تجدد الخلايا فوق الحوض نفسه إلى تراكم سريع حتى إن كانت كل خلية قصيرة العمر."},{"type":"text","text":"تساعد صور الرادار المتتابعة على تتبع الخلايا وتحديد مناطق التجدد والحركة."},{"type":"text","text":"توضح ملفات السبر والرطوبة والقص والاستقرار البيئة التي تدعم الحمل."},{"type":"text","text":"تتأثر السيول بخصائص الأحواض الصغيرة والانحدار ونفاذية التربة والتوسع العمراني."},{"type":"text","text":"يجب الفصل بين التنبؤ بالعاصفة والتنبؤ باستجابة الحوض المائية، مع ربطهما عند إصدار التحذير."},{"type":"text","text":"مثال: تقارب نسيم البحر مع رياح عامة فوق سفح جبلي قد يدعم تطور خلايا مطرية محلية."},{"type":"callout","text":"خلاصة: العواصف والسيول في المنطقة تحتاج دمج التنبؤ الحملي بالرصد والهيدرولوجيا المحلية."}]}',1920,55,'["تحليل بيئة الحمل المحلي","فهم أثر التضاريس والسواحل","تقييم مخاطر الهطول الشديد"]','الظواهر الشتوية الإقليمية'),
('dust-transport-khamsin-and-regional-haze','نقل الغبار والخماسين والعواصف الترابية الإقليمية','مصادر الغبار ومساراته والأنظمة الجوية المسببة للغبار والعوالق.','{"blocks":[{"type":"text","text":"تتأثر العواصف الغبارية في شرق المتوسط بمصادر صحراوية واسعة وبالرياح السطحية والجبهات والاضطرابات الحملية."},{"type":"text","text":"قد تؤدي المنخفضات والرياح الجنوبية أو الجنوبية الشرقية إلى نقل الغبار من شمال أفريقيا والجزيرة العربية نحو مناطق شرق المتوسط."},{"type":"text","text":"تستخدم تسمية الخماسين إقليمياً لوصف فترات من الرياح الدافئة الجافة والغبارية المرتبطة بظروف موسمية معينة، مع اختلاف الاستخدام المحلي."},{"type":"text","text":"تؤثر سرعة الرياح واستقرار الطبقة الحدية ورطوبة التربة والغطاء النباتي في شدة إثارة الغبار."},{"type":"text","text":"قد ينتقل الغبار في طبقات مرتفعة ويؤثر في الإشعاع والرؤية حتى عندما تكون تراكيزه السطحية محدودة."},{"type":"text","text":"تساعد القنوات المرئية وتحت الحمراء ومنتجات الهباء في تمييز بعض حالات الغبار عن السحب."},{"type":"text","text":"تستخدم محطات جودة الهواء والرؤية لتقييم التأثير قرب السطح."},{"type":"text","text":"قد يترافق الغبار مع ارتفاع الحرارة وانخفاض الرطوبة قبل مرور جبهة أو تغير اتجاه الرياح."},{"type":"text","text":"تؤثر الأمطار في إزالة الغبار من الغلاف الجوي عبر الترسيب الرطب."},{"type":"text","text":"تحتاج توقعات الغبار إلى دمج خرائط الرياح والرطوبة والتربة وصور الأقمار ومصادر الانبعاث."},{"type":"text","text":"مثال: رياح جنوبية نشطة فوق مناطق جافة قد ترفع الغبار وتنقله شمالاً قبل وصول كتلة أبرد."},{"type":"callout","text":"خلاصة: الغبار الإقليمي ينتج من تفاعل مصدر السطح مع حركة الهواء والطبقة الحدية والطقس واسع النطاق."}]}',1930,55,'["تحديد مصادر الغبار","فهم آليات النقل الإقليمي","تمييز الغبار عن السحب"]','الظواهر الجوية الإقليمية'),
('orographic-rainfall-coastal-mountains','الأمطار التضاريسية والسواحل والظل المطري','تفاعل تدفق الرطوبة مع الجبال الساحلية وتوزيع الهطول على السفوح.','{"blocks":[{"type":"text","text":"يحدث الهطول التضاريسي عندما يجبر الهواء الرطب على الصعود فوق تضاريس مرتفعة ويبرد حتى الإشباع."},{"type":"text","text":"تعتمد شدة الرفع على اتجاه الرياح بالنسبة إلى السفح واستقرار الهواء ومحتواه الرطوبي."},{"type":"text","text":"قد تتلقى السفوح المواجهة للرياح هطولاً أكبر من السفوح الواقعة في ظل المطر."},{"type":"text","text":"تؤثر ارتفاعات الجبال وانحداراتها وشكل السلاسل في توزيع الرفع والسحب والهطول."},{"type":"text","text":"قد تعزز الرياح البحرية الرطبة الهطول على الجبال الساحلية عندما يكون اتجاهها مناسباً."},{"type":"text","text":"تؤثر حرارة سطح البحر في استقرار الهواء الداخل نحو الساحل وفي مقدار الرطوبة المتاحة."},{"type":"text","text":"قد تتكون سحب منخفضة وضباب على السفوح عند استمرار تدفق الهواء الرطب ووجود رفع مناسب."},{"type":"text","text":"تستخدم محطات متعددة الارتفاعات والرادار وبيانات الأقمار لتقييم التدرج المطري."},{"type":"text","text":"قد تقلل الشبكات ذات المحطات القليلة من تقدير الهطول في المناطق الجبلية بسبب التباين المكاني."},{"type":"text","text":"تحتاج النماذج إلى دقة مكانية وتمثيل تضاريسي مناسب، مع التحقق من الرصد الفعلي."},{"type":"text","text":"مثال: تدفق غربي رطب قد يعزز الهطول على السفوح الغربية لجبال ساحلية ويترك مناطق داخلية في ظل مطري نسبي."},{"type":"callout","text":"خلاصة: المطر التضاريسي يعتمد على اتجاه التدفق والرطوبة واستقرار الهواء وهندسة التضاريس."}]}',1940,55,'["شرح آلية المطر التضاريسي","تحليل اتجاه الرياح بالنسبة للسفح","فهم الظل المطري"]','الظواهر الشتوية الإقليمية'),
('eastern-mediterranean-climate-change-signals','إشارات تغير المناخ في شرق المتوسط','تحليل الاتجاهات الحرارية والهطول والتطرفات وعدم اليقين الإقليمي.','{"blocks":[{"type":"text","text":"يتطلب تقييم تغير المناخ في شرق المتوسط سجلات طويلة ومتجانسة للحرارة والهطول والمتغيرات المائية."},{"type":"text","text":"تظهر دراسات المناخ الإقليمي أهمية تحليل اتجاهات الحرارة والتطرفات الحرارية إلى جانب التغيرات المطرية."},{"type":"text","text":"تختلف إشارات الهطول بين المناطق والفصول، وقد يكون التباين الطبيعي كبيراً مقارنة بالاتجاه طويل الأمد."},{"type":"text","text":"قد تتغير مدة الموسم المطري وتوزيعه وتواتر الفترات الجافة حتى عندما لا يتغير المجموع السنوي بالمقدار نفسه."},{"type":"text","text":"تؤثر حرارة البحر المتوسط في الرطوبة والاستقرار والتفاعلات الجوية الساحلية، لكن الأثر يعتمد على الدورة الجوية أيضاً."},{"type":"text","text":"تستخدم النماذج العالمية والإقليمية والسيناريوهات لتقدير نطاقات التغير المحتملة."},{"type":"text","text":"تتأثر الإسقاطات بعدم اليقين في الانبعاثات والنماذج والتصغير والبيانات المرجعية."},{"type":"text","text":"يجب مقارنة الفترات المستقبلية بخط أساس محدد، وذكر السيناريو والفصل والمقياس المكاني."},{"type":"text","text":"تحتاج دراسة التطرفات إلى مؤشرات مثل موجات الحر والليالي الدافئة والأمطار القصوى والفترات الجافة."},{"type":"text","text":"لا يجوز تعميم نتيجة محطة واحدة على كامل شرق المتوسط بسبب اختلاف الارتفاع والساحل والداخل والتضاريس."},{"type":"text","text":"مثال: قد يظهر اتجاه حراري متقارب بين عدة محطات بينما يختلف اتجاه الهطول مكانياً، ما يستدعي تحليلاً إقليمياً مفصلاً."},{"type":"callout","text":"خلاصة: دراسة تغير المناخ الإقليمي تحتاج سجلات متجانسة ومقارنة متعددة النماذج وتفسيراً حذراً لعدم اليقين."}]}',1950,55,'["تمييز الإشارة المناخية عن التذبذب","تحليل الاتجاهات الإقليمية","فهم حدود الإسقاطات"]','مناخ شرق المتوسط وبلاد الشام'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'مناخ شرق المتوسط وبلاد الشام' then u1.id when 'الأنظمة الجوية الإقليمية' then u2.id when 'الظواهر الشتوية الإقليمية' then u3.id when 'الظواهر الجوية الإقليمية' then u4.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'أنماط الطقس والمناخ في شرق المتوسط وبلاد الشام',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;